import{_ as e,c as t,o as a,a6 as o}from"./chunks/framework.Dk6vZ2f8.js";const g=JSON.parse('{"title":"Micro App Development","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"micro_app_dev/index.md","filePath":"micro_app_dev/index.md","lastUpdated":1793535853000}'),i={name:"micro_app_dev/index.md"},r=o('<h1 id="micro-app-development" tabindex="-1">Micro App Development <a class="header-anchor" href="#micro-app-development" aria-label="Permalink to &quot;Micro App Development&quot;">​</a></h1><p>Sun-Panel V2 fully supports the micro-app ecosystem, building an open and efficient plugin-based system.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The documentation is still being improved. If you are developing, please add the author&#39;s WeChat (95302870) so the author can add you to the developer group for easier communication.</p></div><h2 id="what-is-a-micro-app" tabindex="-1">What is a Micro App <a class="header-anchor" href="#what-is-a-micro-app" aria-label="Permalink to &quot;What is a Micro App&quot;">​</a></h2><p>A micro app is a plugin feature introduced in Sun-Panel V2. Developers can build micro apps just like ordinary web applications, then publish them to Sun-Panel for all users to use.</p><p>Micro apps support two display forms:</p><table tabindex="0"><thead><tr><th>Form</th><th>Description</th><th>Use Case</th></tr></thead><tbody><tr><td><strong>Widget</strong></td><td>Card form, embedded in the navigation page</td><td>Small components such as weather, clock, quick tools</td></tr><tr><td><strong>Page</strong></td><td>Window form, standalone page</td><td>Fully-featured visualization tools or management interfaces</td></tr></tbody></table><ul><li><strong>Page component</strong>: Window form, standalone page. Can be configured via the page type as a widget configuration page or a main page. <img src="https://doc-img.sun-panel.top/microapp-img/picgo-2026-08-e20ed67d77977c544b96d7eab89e95a4.png" alt=""></li><li><strong>Widget component</strong>: Added via the &quot;Add Widget&quot; button in the group toolbar, displayed within the navigation page. <img src="https://doc-img.sun-panel.top/microapp-img/picgo-2026-07-6ecd8453d4b11346b6acb0785749d067.png" alt="size"></li></ul><h2 id="technical-architecture" tabindex="-1">Technical Architecture <a class="header-anchor" href="#technical-architecture" aria-label="Permalink to &quot;Technical Architecture&quot;">​</a></h2><p>Micro apps are built on <strong>Web Components</strong> and the <strong>Lit</strong> framework:</p><ul><li><strong>Web Components</strong> - Native browser standard, truly framework-agnostic</li><li><strong>Lit</strong> - A lightweight Web Components framework maintained by Google, efficient and easy to use</li></ul><h3 id="why-this-tech-stack" tabindex="-1">Why this tech stack? <a class="header-anchor" href="#why-this-tech-stack" aria-label="Permalink to &quot;Why this tech stack?&quot;">​</a></h3><ul><li><strong>Framework-agnostic</strong>: Works seamlessly with Vue, React, or no-framework environments</li><li><strong>High performance</strong>: Near-native rendering performance</li><li><strong>Style isolation</strong>: Shadow DOM provides natural isolation, styles don&#39;t interfere with each other</li></ul><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h2><ul><li>Component-based architecture, simple and efficient development</li><li>Multiple size support: 1×1, 1×2, 2×1, 2×2, 2×4, 1×full, etc.</li><li>Configuration-based development, manage app info through config files</li><li>Automatic dark mode adaptation</li><li>Platform API support: network requests, data nodes, local cache</li><li>Multi-user data isolation</li></ul><h2 id="development-guidelines" tabindex="-1">Development Guidelines <a class="header-anchor" href="#development-guidelines" aria-label="Permalink to &quot;Development Guidelines&quot;">​</a></h2><h3 id="general-rules" tabindex="-1">General Rules <a class="header-anchor" href="#general-rules" aria-label="Permalink to &quot;General Rules&quot;">​</a></h3><ul><li><strong>Must</strong> use the officially provided API for network requests. Directly using native methods like <code>fetch</code>, <code>ajax</code>, <code>axios</code> is prohibited.</li><li><strong>Prohibited</strong> from accessing other micro apps&#39; data (localStorage, IndexedDB, etc.)</li><li><strong>Prohibited</strong> from collecting user data in any form</li><li><strong>Prohibited</strong> from using dangerous methods such as <code>eval</code></li><li>The API provides some basic methods; try to use the API to implement these features. If the API doesn&#39;t provide the functionality you need, contact the author describing your use case to see if related APIs can be added later.</li><li>A single micro app is recommended to contain at most 3 components. If there are too many features, consider splitting into multiple micro apps.</li></ul><h3 id="additional-widget-rules" tabindex="-1">Additional Widget Rules <a class="header-anchor" href="#additional-widget-rules" aria-label="Permalink to &quot;Additional Widget Rules&quot;">​</a></h3><ul><li><strong>Prohibited</strong> from floating layers exceeding the card bounds</li><li><strong>Prohibited</strong> from listening to right-click menu triggers</li></ul><h2 id="ui-collaboration-debugging-tool" tabindex="-1">UI Collaboration Debugging Tool <a class="header-anchor" href="#ui-collaboration-debugging-tool" aria-label="Permalink to &quot;UI Collaboration Debugging Tool&quot;">​</a></h2><p><a href="https://github.com/madrays" target="_blank" rel="noreferrer">@Madrays</a> developed the <a href="https://github.com/madrays/sun-micro-app" target="_blank" rel="noreferrer">UI collaboration debugging tool</a>. Thanks for the hard work!</p><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><ul><li><a href="./quick_start.html">Quick Start</a> - Run Hello World in 5 minutes</li><li><a href="./project_structure.html">Project Structure</a> - Understand directories and files</li><li><a href="./dev_guide.html">Component Development</a> - Learn how to develop components</li><li><a href="./api.html">Platform API</a> - Call platform capabilities</li></ul>',24),n=[r];function l(s,d,c,h,p,u){return a(),t("div",null,n)}const f=e(i,[["render",l]]);export{g as __pageData,f as default};
